// Limpia lo que llega del formulario y descarta bots y envíos incompletos.
// Nada sale de aquí sin pasar por este filtro.

const FREE_MAIL = [
  'gmail.com', 'hotmail.com', 'outlook.com', 'outlook.es', 'yahoo.com',
  'yahoo.es', 'live.com', 'icloud.com', 'aol.com', 'protonmail.com',
  'proton.me', 'gmx.com', 'mail.com', 'yandex.com', 'zoho.com',
];

const clean = (value) => String(value ?? '').trim();
const isEmail = (value) => /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(value);

const results = [];

for (const item of $input.all()) {
  // El webhook v2 mete el cuerpo en `body`; se acepta también plano.
  const src = item.json.body ?? item.json;

  const name = clean(src.name);
  const email = clean(src.email).toLowerCase();
  const phone = clean(src.phone);
  const company = clean(src.company);
  const message = clean(src.message);
  const service = clean(src.service) || 'otro';
  const budget = clean(src.budget) || 'unknown';
  const serviceLabel = clean(src.serviceLabel) || service;
  const budgetLabel = clean(src.budgetLabel) || budget;
  const honeypot = clean(src.website);
  const elapsedMs = Number(src.elapsedMs ?? 0);

  const problems = [];

  // Trampa para bots: el campo está oculto, una persona no puede rellenarlo.
  if (honeypot) problems.push('honeypot');

  // Un humano no completa el formulario en menos de tres segundos.
  if (elapsedMs > 0 && elapsedMs < 3000) problems.push('demasiado rapido');

  if (name.length < 2) problems.push('nombre');
  if (!isEmail(email)) problems.push('email');
  if (message.length < 10) problems.push('mensaje');

  // Spam habitual: mensajes plagados de enlaces u ofertas de SEO.
  const links = (message.match(/https?:\/\//g) || []).length;
  if (links >= 3) problems.push('exceso de enlaces');
  if (/(seo services|backlinks|criptomoned|bitcoin|casino|viagra)/i.test(message)) {
    problems.push('contenido sospechoso');
  }

  const domain = email.split('@')[1] || '';

  results.push({
    json: {
      valid: problems.length === 0,
      problems,
      name,
      firstName: name.split(' ')[0] || name,
      email,
      domain,
      corporateEmail: Boolean(domain) && !FREE_MAIL.includes(domain),
      phone,
      company,
      service,
      serviceLabel,
      budget,
      budgetLabel,
      message,
      page: clean(src.page),
      source: clean(src.source) || 'web',
      receivedAt: new Date().toISOString(),
    },
  });
}

return results;

// Puntúa el lead con reglas explícitas. Sin IA a propósito: es gratis,
// instantáneo y siempre puedes explicar por qué un lead sacó la nota que sacó.
// Los pesos están arriba para que los ajustes con los datos reales.

const PESOS = {
  presupuesto: { gt7k: 35, '3k-7k': 28, '1k-3k': 20, lt1k: 6, unknown: 12 },
  servicio: {
    automatizacion: 12,
    chatbot: 12,
    tienda: 10,
    web: 7,
    landing: 7,
    optimizacion: 6,
    otro: 2,
  },
  telefono: 12,
  empresa: 8,
  emailCorporativo: 10,
  mensajeLargo: 12,
  mensajeMedio: 8,
  mensajeCorto: 4,
  urgencia: 8,
  descalificador: -25,
};

// Umbrales de clasificación. Calibrados para que un autónomo con correo de
// Gmail y presupuesto de 1.000-3.000 € siga siendo un lead B: la mayoría de
// los negocios locales no tienen dominio propio y son clientes perfectamente
// buenos. Súbelos el día que te sobren leads.
const UMBRALES = { A: 65, B: 40, C: 22 };

const URGENCIA = /(urgente|cuanto antes|lo antes posible|esta semana|para ya|inmediato|ya tengo|presupuesto aprobado|necesito para)/i;
const DESCARTE = /(gratis|sin coste|sin presupuesto|practicas|prácticas|estudiante|intercambio|colaboraci[oó]n|a cambio de visibilidad|porcentaje de las ventas)/i;

const esc = (texto) =>
  String(texto ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

const results = [];

for (const item of $input.all()) {
  const lead = item.json;
  let score = 0;
  const reasons = [];

  const addPoints = (points, why) => {
    if (!points) return;
    score += points;
    reasons.push((points > 0 ? '+' : '') + points + ' ' + why);
  };

  addPoints(PESOS.presupuesto[lead.budget] ?? PESOS.presupuesto.unknown, 'presupuesto: ' + lead.budgetLabel);
  addPoints(PESOS.servicio[lead.service] ?? PESOS.servicio.otro, 'servicio: ' + lead.serviceLabel);

  if (lead.phone) addPoints(PESOS.telefono, 'dejó teléfono');
  if (lead.company) addPoints(PESOS.empresa, 'indicó empresa');
  if (lead.corporateEmail) addPoints(PESOS.emailCorporativo, 'email corporativo (' + lead.domain + ')');

  const largo = lead.message.length;
  if (largo >= 250) addPoints(PESOS.mensajeLargo, 'mensaje detallado');
  else if (largo >= 100) addPoints(PESOS.mensajeMedio, 'mensaje con contexto');
  else addPoints(PESOS.mensajeCorto, 'mensaje breve');

  if (URGENCIA.test(lead.message)) addPoints(PESOS.urgencia, 'señales de urgencia');
  if (DESCARTE.test(lead.message)) addPoints(PESOS.descalificador, 'pide trabajo sin pagar');

  score = Math.max(0, Math.min(100, score));

  let tier, tierLabel, emoji, action, slaHours;
  if (score >= UMBRALES.A) {
    tier = 'A'; tierLabel = 'CALIENTE'; emoji = '🔥';
    action = 'Llamar hoy. Si no contesta, WhatsApp y segundo intento mañana.';
    slaHours = 2;
  } else if (score >= UMBRALES.B) {
    tier = 'B'; tierLabel = 'TEMPLADO'; emoji = '🟡';
    action = 'Enviar propuesta con precio cerrado en menos de 24 h.';
    slaHours = 24;
  } else if (score >= UMBRALES.C) {
    tier = 'C'; tierLabel = 'FRÍO'; emoji = '🔵';
    action = 'Responder con preguntas para concretar alcance y presupuesto.';
    slaHours = 48;
  } else {
    tier = 'D'; tierLabel = 'REVISAR'; emoji = '⚪';
    action = 'Revisar a mano antes de invertir tiempo.';
    slaHours = 72;
  }

  const fecha = new Date();
  const sello = fecha.toISOString().slice(0, 10).replace(/-/g, '');
  const leadId = 'LD-' + sello + '-' + Math.random().toString(36).slice(2, 7).toUpperCase();
  const dueAt = new Date(fecha.getTime() + slaHours * 3600 * 1000).toISOString();

  const lineas = [
    emoji + ' <b>LEAD ' + tier + ' · ' + tierLabel + '</b>  —  ' + score + '/100',
    '',
    '<b>' + esc(lead.name) + '</b>' + (lead.company ? ' · ' + esc(lead.company) : ''),
    '✉️ ' + esc(lead.email),
    lead.phone ? '📞 ' + esc(lead.phone) : '📞 no dejó teléfono',
    '',
    '<b>Quiere:</b> ' + esc(lead.serviceLabel),
    '<b>Presupuesto:</b> ' + esc(lead.budgetLabel),
    '',
    '<b>Mensaje</b>',
    '<i>' + esc(lead.message.slice(0, 600)) + '</i>',
    '',
    '<b>Por qué esta nota</b>',
    reasons.map((r) => '· ' + esc(r)).join('\n'),
    '',
    '👉 <b>' + esc(action) + '</b>',
    'Responder antes de: ' + dueAt.slice(0, 16).replace('T', ' ') + ' UTC',
    '',
    '<code>' + leadId + '</code>',
  ];

  const notifyText = lineas.join('\n');

  results.push({
    json: {
      ...lead,
      leadId,
      score,
      tier,
      tierLabel,
      action,
      slaHours,
      dueAt,
      reasons,
      reasonsText: reasons.join(' | '),
      notifyText,
      // Misma información sin etiquetas HTML, para WhatsApp o SMS.
      notifyPlain: notifyText.replace(/<[^>]+>/g, ''),
      autoReplySubject: 'Recibimos tu solicitud (' + leadId + ')',
      autoReplyBody: [
        'Hola ' + lead.firstName + ',',
        '',
        'Gracias por escribirnos. Ya tenemos tu solicitud y la estamos revisando.',
        '',
        'Nos has pedido: ' + lead.serviceLabel,
        '',
        'Te respondemos en menos de 24 horas laborables con dos cosas: una propuesta de cómo lo abordaríamos y un precio cerrado, sin sorpresas. Si mientras tanto quieres adelantarnos algo, responde a este mismo correo.',
        '',
        'Referencia de tu solicitud: ' + leadId,
        '',
        'Un saludo,',
        'El equipo',
      ].join('\n'),
    },
  });
}

return results;

// Deja solo las columnas de la hoja. Sin esto, Google Sheets crearía una
// columna por cada campo interno del flujo.

return $input.all().map((item) => ({
  json: {
    ID: item.json.leadId,
    Fecha: item.json.receivedAt,
    Nombre: item.json.name,
    Email: item.json.email,
    Telefono: item.json.phone,
    Empresa: item.json.company,
    Servicio: item.json.serviceLabel,
    Presupuesto: item.json.budgetLabel,
    Mensaje: item.json.message,
    Score: item.json.score,
    Clasificacion: item.json.tier,
    Estado: 'Nuevo',
    Accion: item.json.action,
    ResponderAntesDe: item.json.dueAt,
    Motivos: item.json.reasonsText,
    Origen: item.json.source,
    Pagina: item.json.page,
    // Prepara el terreno para varios clientes: cuando montéis el formulario
    // de un cliente, duplicad el flujo y cambiad este valor.
    Cliente: 'Interno',
  },
}));
